-/** Convert `value` from one unit to another of the same kind. See README.md. */
+import { LINEAR_UNITS, TEMPERATURE_UNITS } from "./units.ts";
+
+function linearConvert(value: number, from: string, to: string): number {
+  if (from === to) return value;
+  const fromUnit = LINEAR_UNITS[from];
+  if (!fromUnit) throw new Error("unknown unit: " + from);
+  const toUnit = LINEAR_UNITS[to];
+  if (!toUnit) throw new Error("unknown unit: " + to);
+  if (fromUnit.kind !== toUnit.kind) {
+    throw new Error("cannot convert " + from + " to " + to);
+  }
+  return (value * fromUnit.factor) / toUnit.factor;
+}
+
+function tempToCelsius(value: number, from: string): number {
+  switch (from) {
+    case "C": return value;
+    case "F": return (value - 32) * 5 / 9;
+    case "K": return value - 273.15;
+    default: throw new Error("unknown unit: " + from);
+  }
+}
+
+function celsiusToTemp(value: number, to: string): number {
+  switch (to) {
+    case "C": return value;
+    case "F": return value * 9 / 5 + 32;
+    case "K": return value + 273.15;
+    default: throw new Error("unknown unit: " + to);
+  }
+}
